<script setup lang="ts">import {computed} from 'vue';import type {Run} from '../types/domain';import {number} from '../utils/format';const props=defineProps<{run:Run}>();const cells=computed(()=>props.run.result.cells||[]);const bounds=computed(()=>{const vals=cells.value.flatMap(c=>[c.ci_low??c.mean,c.ci_high??c.mean]);const lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max(1,(hi-lo)*.15);return [lo-pad,hi+pad];});const sx=(a:string)=>80+(props.run.result.a_levels?.indexOf(a)||0)*430/Math.max(1,(props.run.result.a_levels?.length||2)-1);const sy=(v:number)=>260-(v-bounds.value[0])/(bounds.value[1]-bounds.value[0])*210;const colors=['#304455','#ad7445','#6f7661','#845e70'];</script><template><section class="interaction-plot"><div class="section-heading"><h2>温度作用，随釉层怎样变化</h2><span>处理格均值与逐项t区间</span></div><svg v-if="cells.length" viewBox="0 0 590 320" role="img" aria-label="温度与釉层处理格均值交互图"><g v-for="t in [0,.25,.5,.75,1]" :key="t" class="plot-grid"><line x1="65" x2="535" :y1="50+t*210" :y2="50+t*210"/><text x="53" :y="54+t*210" text-anchor="end">{{number(bounds[1]-t*(bounds[1]-bounds[0]),1)}}</text></g><g v-for="(glaze,i) in run.result.b_levels" :key="glaze"><polyline :points="cells.filter(c=>c.glaze===glaze).map(c=>sx(c.temperature)+','+sy(c.mean)).join(' ')" fill="none" :stroke="colors[i]" stroke-width="2"/><g v-for="c in cells.filter(c=>c.glaze===glaze)" :key="c.temperature"><line :x1="sx(c.temperature)" :x2="sx(c.temperature)" :y1="sy(c.ci_low!)" :y2="sy(c.ci_high!)" :stroke="colors[i]"/><circle :cx="sx(c.temperature)" :cy="sy(c.mean)" r="4.5" :fill="colors[i]"><title>{{glaze}} / {{c.temperature}} / 均值{{c.mean}}</title></circle></g></g><text v-for="temp in run.result.a_levels" :key="temp" :x="sx(temp)" y="285" text-anchor="middle" class="axis-label">{{temp}}°C</text><text x="65" y="25" class="axis-label">抗折强度 / MPa</text></svg><div class="legend"><span v-for="(b,i) in run.result.b_levels" :key="b" :style="{color:colors[i]}">● {{b}}</span><small>区间使用统一格内MSE；连线只辅助读取固定温度水平。</small></div></section></template>
